import{_ as a,o as t,c as n,a6 as s}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"认证","description":"challenge/credentials 语法、realm、token68、Basic 与 Bearer 方案及代理认证字段。","frontmatter":{"title":"认证","description":"challenge/credentials 语法、realm、token68、Basic 与 Bearer 方案及代理认证字段。","source":"https://daiw.org/manual/http11/authentication"},"headers":[],"relativePath":"manual/computer-programming/http11/authentication.md","filePath":"manual/computer-programming/http11/authentication.md"}'),o={name:"manual/computer-programming/http11/authentication.md"};function i(r,e,l,c,d,p){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="认证" tabindex="-1">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to &quot;认证&quot;">​</a></h1><h2 id="四个核心字段" tabindex="-1">四个核心字段 <a class="header-anchor" href="#四个核心字段" aria-label="Permalink to &quot;四个核心字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>方向</th><th>配对状态码</th><th>性质</th></tr></thead><tbody><tr><td><code>WWW-Authenticate</code></td><td>响应</td><td><code>401</code></td><td>端到端</td></tr><tr><td><code>Authorization</code></td><td>请求</td><td>—</td><td>端到端</td></tr><tr><td><code>Proxy-Authenticate</code></td><td>响应</td><td><code>407</code></td><td><strong>逐跳</strong></td></tr><tr><td><code>Proxy-Authorization</code></td><td>请求</td><td>—</td><td><strong>逐跳</strong></td></tr></tbody></table><p>代理认证字段<strong>不得</strong>被转发，必须在每一跳独立处理。</p><h2 id="挑战语法" tabindex="-1">挑战语法 <a class="header-anchor" href="#挑战语法" aria-label="Permalink to &quot;挑战语法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WWW-Authenticate = #challenge</span></span>
<span class="line"><span>challenge   = auth-scheme [ 1*SP ( token68 / #auth-param ) ]</span></span>
<span class="line"><span>auth-scheme = token</span></span>
<span class="line"><span>auth-param  = token BWS &quot;=&quot; BWS ( token / quoted-string )</span></span>
<span class="line"><span>token68     = 1*( ALPHA / DIGIT / &quot;-&quot; / &quot;.&quot; / &quot;_&quot; / &quot;~&quot; / &quot;+&quot; / &quot;/&quot; ) *&quot;=&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WWW-Authenticate: Basic realm=&quot;Admin Area&quot;, charset=&quot;UTF-8&quot;</span></span>
<span class="line"><span>WWW-Authenticate: Bearer realm=&quot;api&quot;, error=&quot;invalid_token&quot;</span></span>
<span class="line"><span>WWW-Authenticate: Newauth realm=&quot;apps&quot;, Basic realm=&quot;simple&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>解析要点：</p><ul><li><code>auth-scheme</code> 与其后内容之间是 <strong>1 个或多个 SP</strong>，不是 OWS。</li><li><strong><code>token68</code> 与 <code>auth-param</code> 二选一</strong>，不可混用。</li><li>多个挑战用逗号分隔——这使解析变得棘手：逗号既分隔挑战、也分隔同一挑战内的参数。解析器<strong>必须</strong>靠「是否形如 <code>scheme SP</code>」来判断新挑战的起点。</li><li><code>401</code> 响应 <strong>MUST</strong> 带至少一个挑战。</li><li>客户端<strong>应</strong>选择自己支持的<strong>最强</strong>方案，而非第一个。</li></ul><h3 id="realm-参数" tabindex="-1">realm 参数 <a class="header-anchor" href="#realm-参数" aria-label="Permalink to &quot;realm 参数&quot;">​</a></h3><ul><li><strong>所有方案通用</strong>的唯一保留参数，定义受保护空间。</li><li>值 <strong>MUST</strong> 是 <code>quoted-string</code>（不可用裸 token），且<strong>大小写敏感</strong>。</li><li>客户端据 <code>(origin, realm)</code> 决定复用哪份凭据。</li><li><code>Bearer</code> 中 <code>realm</code> 可选。</li></ul><h2 id="凭据语法" tabindex="-1">凭据语法 <a class="header-anchor" href="#凭据语法" aria-label="Permalink to &quot;凭据语法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization = credentials</span></span>
<span class="line"><span>credentials   = auth-scheme [ 1*SP ( token68 / #auth-param ) ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>auth-scheme</code> <strong>大小写不敏感</strong>（<code>basic</code> == <code>Basic</code>）；参数名不敏感，参数值除非另有规定否则敏感。</p><h2 id="basic" tabindex="-1">Basic <a class="header-anchor" href="#basic" aria-label="Permalink to &quot;Basic&quot;">​</a></h2><p>RFC 7617。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>credentials = &quot;Basic&quot; SP token68</span></span>
<span class="line"><span>token68     = base64( user-id &quot;:&quot; password )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Basic YWxhZGRpbjpvcGVuc2VzYW1l</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>约束：</p><ul><li><code>user-id</code> <strong>不得含冒号</strong>——第一个冒号即分隔符，密码中的冒号合法。</li><li>编码字符集历史上未定义（多为 ISO-8859-1），服务端可用挑战中的 <code>charset=&quot;UTF-8&quot;</code> 声明期望 UTF-8。该参数<strong>只允许</strong>取值 <code>UTF-8</code>。</li><li><strong>Base64 不是加密</strong>——明文等价。必须在 TLS 上使用。</li><li>客户端可在收到 <code>401</code> 前<strong>抢先</strong>发送（避免额外往返），Basic 是少数支持抢先认证的方案。</li></ul><h2 id="bearer" tabindex="-1">Bearer <a class="header-anchor" href="#bearer" aria-label="Permalink to &quot;Bearer&quot;">​</a></h2><p>RFC 6750。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer mF_9.B5f-4.1JqM</span></span>
<span class="line"><span>WWW-Authenticate: Bearer realm=&quot;api&quot;, error=&quot;invalid_token&quot;,</span></span>
<span class="line"><span>                  error_description=&quot;The access token expired&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>令牌是 <code>token68</code>，持有即可用（bearer = 持票人）——<strong>必须</strong> TLS 传输。</li><li>错误参数：<code>invalid_request</code>（→ <code>400</code>）、<code>invalid_token</code>（→ <code>401</code>）、<code>insufficient_scope</code>（→ <code>403</code>）。</li><li><strong>MUST NOT</strong> 把令牌放进 URI query——会进日志、Referer 与浏览器历史。</li></ul><h2 id="digest-已不推荐" tabindex="-1">Digest（已不推荐） <a class="header-anchor" href="#digest-已不推荐" aria-label="Permalink to &quot;Digest（已不推荐）&quot;">​</a></h2><p>RFC 7616。用挑战-应答避免明文传输密码，参数含 <code>nonce</code>、<code>qop</code>、<code>algorithm</code>、<code>opaque</code> 等。</p><p>现状：实现复杂、与现代密码存储（服务端需存可逆或特定哈希）冲突、且 TLS 已解决明文问题。<strong>新系统不应使用</strong>，改用 TLS + Bearer/OAuth2。</p><h2 id="authentication-info" tabindex="-1">Authentication-Info <a class="header-anchor" href="#authentication-info" aria-label="Permalink to &quot;Authentication-Info&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authentication-Info = #auth-param</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在<strong>成功</strong>响应中携带认证相关的补充信息（如 Digest 的 <code>nextnonce</code>、双向认证的服务端应答）。对应的代理版是 <code>Proxy-Authentication-Info</code>。</p><h2 id="安全约束-must-级" tabindex="-1">安全约束（MUST 级） <a class="header-anchor" href="#安全约束-must-级" aria-label="Permalink to &quot;安全约束（MUST 级）&quot;">​</a></h2><ul><li>凭据<strong>跨 origin 重定向时 MUST NOT 携带</strong>。跳到不同 origin 必须重新认证。</li><li>带 <code>Authorization</code> 的请求，其响应<strong>默认不可被共享缓存存储</strong>（见<a href="/Front2Full/manual/computer-programming/http11/caching">缓存</a>）；需存储时必须显式 <code>public</code>/<code>s-maxage</code>/<code>must-revalidate</code>。</li><li><code>401</code> 与 <code>403</code> 的选择见<a href="/Front2Full/manual/computer-programming/http11/status-4xx">状态码 4xx</a>：能换凭据解决用 <code>401</code>，换了也没用用 <code>403</code>。</li><li>认证失败的响应<strong>不应</strong>泄露「用户不存在」与「密码错误」的区别。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/cookies">Cookie</a>——Set-Cookie 属性全集与安全前缀。</p>`,33)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
